INSERT INTO zhishi_notices (id, real, source, publish_date, title, event, audience, deadline, countdown, materials, entry, confidence, priority, points, digest_one, digest_points, raw, url, site, unit, src_generated_at) VALUES ('ahau-012', TRUE, '图书馆', '2026-10-29', '公告2026.10.29关于举办第八届“ ProQuest杯”外文文献检索答题大赛的通知', '学科竞赛', NULL, NULL, NULL, NULL, NULL, 0.5, 'medium', '[{"text": "在全球化学术交流日益紧密与数智化浪潮深度赋能的双重驱动下，学术研究正经历着前所未有的范式变革", "quote": "在全球化学术交流日益紧密与数智化浪潮深度赋能的双重驱动下，学术研究正经历着前所未有的范式变革"}]'::jsonb, '学科竞赛：公告2026.10.29关于举办第八届“ ProQuest杯”外文文献检索答题大', '[{"text": "在全球化学术交流日益紧密与数智化浪潮深度赋能的双重驱动下，学术研究正经历着前所未有的范式变革", "quote": "在全球化学术交流日益紧密与数智化浪潮深度赋能的双重驱动下，学术研究正经历着前所未有的范式变革"}]'::jsonb, '在全球化学术交流日益紧密与数智化浪潮深度赋能的双重驱动下，学术研究正经历着前所未有的范式变革。人工智能、大数据等前沿技术的深度介入，不仅重塑了知识的生产与传播方式，也对高校学子的信息素养与全球学术视野提出了更高要求。 为推动我省高校信息素养教育向纵深发展，全面提升大学生外文文献检索能力与学术资源利用水平，安徽省高等学校数字图书馆联合ProQuest（科睿唯安），特举办第八届“ProQuest杯”外文文献检索答题大赛。 一、组织单位 主办单位： 安徽省高等学校数字图书馆 协办单位： 安徽省各高校图书馆 承办单位： 北', 'https://lib.ahau.edu.cn/info/2401/55381.htm', '图书馆 · 新闻公告', 'lib', '2026-11-04 13:33:17') ON CONFLICT (id) DO UPDATE SET source=EXCLUDED.source, publish_date=EXCLUDED.publish_date, title=EXCLUDED.title, event=EXCLUDED.event, deadline=EXCLUDED.deadline, points=EXCLUDED.points, digest_one=EXCLUDED.digest_one, digest_points=EXCLUDED.digest_points, raw=EXCLUDED.raw, url=EXCLUDED.url, site=EXCLUDED.site, unit=EXCLUDED.unit, src_generated_at=EXCLUDED.src_generated_at